(function(window) {
  'use strict';

  function Driver(options) {
    this.options = Object.assign({
      animate: true,
      opacity: 0.75,
      padding: 6,
      allowClose: true,
      overlayClickNext: false,
      doneBtnText: 'Done',
      closeBtnText: '✕',
      nextBtnText: 'Next →',
      prevBtnText: '← Back',
    }, options || {});

    this.steps = [];
    this.currentStep = -1;
    this.overlay = null;
    this.popover = null;
    this.activeElement = null;
  }

  Driver.prototype.setSteps = function(steps) {
    this.steps = steps || [];
    return this;
  };

  Driver.prototype.start = function(stepIndex) {
    if (!this.steps || this.steps.length === 0) return;
    this.currentStep = typeof stepIndex === 'number' ? stepIndex : 0;
    this.createOverlay();
    this.showStep(this.currentStep);
  };

  Driver.prototype.createOverlay = function() {
    if (this.overlay) return;
    this.overlay = document.createElement('div');
    this.overlay.className = 'driver-overlay';
    var self = this;
    this.overlay.addEventListener('click', function() {
      if (self.options.allowClose) {
        self.destroy();
      }
    });
    document.body.appendChild(this.overlay);
  };

  Driver.prototype.showStep = function(index) {
    if (index < 0 || index >= this.steps.length) {
      this.destroy();
      return;
    }

    this.currentStep = index;
    var step = this.steps[index];
    var targetEl = typeof step.element === 'string' ? document.querySelector(step.element) : step.element;

    if (this.activeElement) {
      this.activeElement.classList.remove('driver-active-element');
    }

    if (targetEl) {
      this.activeElement = targetEl;
      targetEl.classList.add('driver-active-element');
      
      // Perform trigger callbacks before calculating position
      if (step.onHighlightStarted && typeof step.onHighlightStarted === 'function') {
        try { step.onHighlightStarted(targetEl); } catch (e) {}
      }

      // Smooth scroll target element into viewport
      targetEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
    } else {
      this.activeElement = null;
      if (step.onHighlightStarted && typeof step.onHighlightStarted === 'function') {
        try { step.onHighlightStarted(null); } catch (e) {}
      }
    }

    this.renderPopover(step, targetEl, index);
  };

  Driver.prototype.renderPopover = function(step, targetEl, index) {
    if (this.popover) {
      this.popover.remove();
    }

    var popover = document.createElement('div');
    popover.className = 'driver-popover';

    var closeHtml = this.options.allowClose ? '<button class="driver-popover-close-btn" aria-label="Close">✕</button>' : '';
    var titleHtml = step.popover && step.popover.title ? '<div class="driver-popover-title">' + step.popover.title + '</div>' : '';
    var descHtml = step.popover && step.popover.description ? '<div class="driver-popover-description">' + step.popover.description + '</div>' : '';
    
    var currentStepNum = (step.popover && step.popover.currentStepNum) ? step.popover.currentStepNum : (index + 1);
    var totalStepsNum = (step.popover && step.popover.totalSteps) ? step.popover.totalSteps : this.steps.length;
    var isFirst = (step.popover && step.popover.isFirst !== undefined) ? step.popover.isFirst : (index === 0);
    var isLast = (step.popover && step.popover.isLast !== undefined) ? step.popover.isLast : (index === this.steps.length - 1);
    
    var prevBtn = isFirst ? '' : '<button class="driver-popover-btn driver-popover-prev-btn">' + (step.popover && step.popover.prevBtnText || this.options.prevBtnText) + '</button>';
    var nextBtn = isLast ? '<button class="driver-popover-btn driver-popover-next-btn">' + (step.popover && step.popover.doneBtnText || this.options.doneBtnText) + '</button>'
                         : '<button class="driver-popover-btn driver-popover-next-btn">' + (step.popover && step.popover.nextBtnText || this.options.nextBtnText) + '</button>';

    var progressText = currentStepNum + ' of ' + totalStepsNum;

    popover.innerHTML = closeHtml + titleHtml + descHtml +
      '<div class="driver-popover-footer">' +
        '<span class="driver-popover-progress">' + progressText + '</span>' +
        '<div class="driver-popover-btn-group">' + prevBtn + nextBtn + '</div>' +
      '</div>';

    document.body.appendChild(popover);
    this.popover = popover;

    // Position popover relative to targetEl or center
    var side = step.popover ? step.popover.side : 'bottom';
    this.positionPopover(popover, targetEl, side);

    // Re-adjust position after smooth scroll settles
    var self = this;
    setTimeout(function() {
      if (self.popover && self.activeElement) {
        self.positionPopover(self.popover, self.activeElement, side);
      }
    }, 120);
    setTimeout(function() {
      if (self.popover && self.activeElement) {
        self.positionPopover(self.popover, self.activeElement, side);
      }
    }, 350);

    var self = this;
    var closeBtnEl = popover.querySelector('.driver-popover-close-btn');
    if (closeBtnEl) {
      closeBtnEl.addEventListener('click', function() { self.destroy(); });
    }

    var prevBtnEl = popover.querySelector('.driver-popover-prev-btn');
    if (prevBtnEl) {
      prevBtnEl.addEventListener('click', function() { self.prev(); });
    }

    var nextBtnEl = popover.querySelector('.driver-popover-next-btn');
    if (nextBtnEl) {
      nextBtnEl.addEventListener('click', function() {
        if (step.onNext && typeof step.onNext === 'function') {
          step.onNext(self);
        }
        self.next();
      });
    }
  };

  Driver.prototype.positionPopover = function(popover, targetEl, side) {
    var scrollTop = window.pageYOffset || document.documentElement.scrollTop;
    var scrollLeft = window.pageXOffset || document.documentElement.scrollLeft;
    var viewportWidth = window.innerWidth;
    var viewportHeight = window.innerHeight;

    if (!targetEl) {
      popover.style.position = 'fixed';
      popover.style.top = '50%';
      popover.style.left = '50%';
      popover.style.transform = 'translate(-50%, -50%)';
      return;
    }

    popover.style.position = 'absolute';
    popover.style.transform = 'none';

    var rect = targetEl.getBoundingClientRect();
    var popRect = popover.getBoundingClientRect();

    // Check if targetEl is invisible or 0x0 size
    if (rect.width === 0 && rect.height === 0) {
      var centerTop = scrollTop + (viewportHeight / 2) - (popRect.height / 2);
      var centerLeft = scrollLeft + (viewportWidth / 2) - (popRect.width / 2);
      popover.style.top = Math.max(scrollTop + 15, centerTop) + 'px';
      popover.style.left = Math.max(scrollLeft + 15, centerLeft) + 'px';
      return;
    }

    var top = 0;
    var left = 0;

    side = side || 'bottom';

    if (side === 'center') {
      top = scrollTop + (viewportHeight / 2) - (popRect.height / 2);
      left = scrollLeft + (viewportWidth / 2) - (popRect.width / 2);
    } else if (side === 'top') {
      top = rect.top + scrollTop - popRect.height - 12;
      left = rect.left + scrollLeft + (rect.width / 2) - (popRect.width / 2);
      if (top < scrollTop + 15) {
        top = rect.bottom + scrollTop + 12;
      }
    } else if (side === 'bottom') {
      top = rect.bottom + scrollTop + 12;
      left = rect.left + scrollLeft + (rect.width / 2) - (popRect.width / 2);
      if (top + popRect.height > scrollTop + viewportHeight - 15) {
        top = rect.top + scrollTop - popRect.height - 12;
      }
    } else if (side === 'right') {
      left = rect.right + scrollLeft + 12;
      top = rect.top + scrollTop + (rect.height / 2) - (popRect.height / 2);
      if (left + popRect.width > scrollLeft + viewportWidth - 15) {
        left = rect.left + scrollLeft - popRect.width - 12;
      }
    } else if (side === 'left') {
      left = rect.left + scrollLeft - popRect.width - 12;
      top = rect.top + scrollTop + (rect.height / 2) - (popRect.height / 2);
      if (left < scrollLeft + 15) {
        left = rect.right + scrollLeft + 12;
      }
    }

    // Viewport bounds clamping
    var minTop = scrollTop + 15;
    var maxTop = scrollTop + viewportHeight - popRect.height - 15;
    if (maxTop < minTop) maxTop = minTop;

    if (top < minTop) top = minTop;
    if (top > maxTop) top = maxTop;

    var minLeft = scrollLeft + 15;
    var maxLeft = scrollLeft + viewportWidth - popRect.width - 15;
    if (maxLeft < minLeft) maxLeft = minLeft;

    if (left < minLeft) left = minLeft;
    if (left > maxLeft) left = maxLeft;

    popover.style.top = Math.round(top) + 'px';
    popover.style.left = Math.round(left) + 'px';
  };

  Driver.prototype.next = function() {
    if (this.currentStep < this.steps.length - 1) {
      this.showStep(this.currentStep + 1);
    } else {
      this.destroy();
    }
  };

  Driver.prototype.prev = function() {
    if (this.currentStep > 0) {
      this.showStep(this.currentStep - 1);
    }
  };

  Driver.prototype.destroy = function() {
    if (this.options.onDestroyStarted && typeof this.options.onDestroyStarted === 'function') {
      try { this.options.onDestroyStarted(); } catch (e) {}
    }
    if (this.activeElement) {
      this.activeElement.classList.remove('driver-active-element');
      this.activeElement = null;
    }
    if (this.overlay) {
      this.overlay.remove();
      this.overlay = null;
    }
    if (this.popover) {
      this.popover.remove();
      this.popover = null;
    }
    this.currentStep = -1;
  };

  window.Driver = Driver;
})(window);
